 public void Open(LevelData data){EndStroke();history.Clear();Draft=data.Clone();saved=data.Clone();Dirty=false;tool=PaintTool.Wall;EditPage();}
 void SelectTool(){foreach(var pair in tools){var c=pair.Value.colors;c.normalColor=pair.Key==tool?StudioUI.Accent:StudioUI.PanelColor*1.7f;pair.Value.colors=c;}} void RecheckDirty(){Dirty=!EditorHistory.EqualsSaved(saved,Draft);UpdateHeading();}
 void EndStroke(){if(Draft!=null)history.Commit(Draft);stroke=false;previous=null;visited.Clear();UpdateHistoryButtons();}
