 void Update(){if(modal){if(Preview!=null&&previewWon&&Input.GetKeyDown(KeyCode.Z)){CloseDialog();Preview.Undo();previewWon=false;completionPulse=false;board.Show(Draft,Preview);PreviewStatus();}return;}if(Preview!=null){if(!PlayInput.Typing&&Input.GetKeyDown(KeyCode.Escape)){ReturnToEditor();return;}if(Input.GetKeyDown(KeyCode.Z)||Input.GetKeyDown(KeyCode.R)){if(PlayInput.Tick(Preview)){previewWon=false;completionPulse=false;board.Show(Draft,Preview);PreviewStatus();}return;}if(Preview.Won&&!board.Busy&&!previewWon){if(!completionPulse){completionPulse=true;board.Celebrate();return;}previewWon=true;FeedbackAudio.Play("complete");Dialog("MISSION COMPLETE!\n"+Draft.name+"\nMoves: "+Preview.Moves+"    Pushes: "+Preview.Pushes,()=>{CloseDialog();ReturnToEditor();},()=>{CloseDialog();Preview.Restart();previewWon=false;completionPulse=false;board.Show(Draft,Preview);PreviewStatus();},"Return to Editor","Retry");return;}if(!board.Busy&&!PlayInput.Typing){var direction=PlayInput.Direction();if(direction.HasValue){if(Preview.Move(direction.Value)){board.Animate(Draft,Preview);PreviewStatus();}else board.Blocked(direction.Value);}}return;}if(!board||Draft==null)return;if(!PlayInput.Typing&&(Input.GetKey(KeyCode.LeftControl)||Input.GetKey(KeyCode.RightControl))){if(Input.GetKeyDown(KeyCode.Z)){HistoryStep(false);return;}if(Input.GetKeyDown(KeyCode.Y)){HistoryStep(true);return;}}bool blocked=PlayInput.Typing||(EventSystem.current&&EventSystem.current.IsPointerOverGameObject());Cell cell=default;bool valid=!blocked&&board.Pick(Input.mousePosition,out cell);board.Hover(valid?(Cell?)cell:null);if(Input.GetMouseButtonUp(0))EndStroke();if(Input.GetMouseButtonDown(0)){stroke=valid;visited.Clear();previous=null;if(valid)history.Begin(Draft);}if(!valid){previous=null;return;}if(!stroke||!Input.GetMouseButton(0))return;bool changed=false;foreach(var c in DraftRules.Line(previous??cell,cell)){if(!visited.Add(c))continue;if(DraftRules.Paint(Draft,c,tool,out string error))changed=true;else if(error!=null)Message(error);}previous=cell;if(changed){RecheckDirty();board.Show(Draft);Message("Map updated. Unsaved changes.");}}
